import{_ as t,o,c as e,ag as a}from"./chunks/framework.DaAXJYxM.js";const d=JSON.parse('{"title":"第111章 八周","description":"","frontmatter":{},"headers":[],"relativePath":"第111章_八周.md","filePath":"第111章_八周.md"}'),_={name:"第111章_八周.md"};function u(r,p,q,n,s,c){return o(),e("div",null,[...p[0]||(p[0]=[a('<h1 id="第111章-八周" tabindex="-1">第111章 八周 <a class="header-anchor" href="#第111章-八周" aria-label="Permalink to &quot;第111章 八周&quot;">​</a></h1><p>那年冬天我把那八周摊在桌上。</p><p>我说摊在桌上是真的摊在桌上。</p><p>我打印了。</p><p>我拿公司那台打印机打了十六页纸。</p><p>左半边是她那边发的。</p><p>右半边是我这边发的。</p><p>我按日期排，一天一行。</p><p>我为什么要打出来。</p><p>因为我在屏幕上读了三遍，我一直以为我在读同一件事。</p><p>我把它打印出来，一张一张并排放，我才看出来那是两件事。</p><p>我先讲头两周。</p><p>第一周，她在算钱。</p><p>她那边的记录里全是数字：三千二、两千一、四千七、九百、六十八、四十块、二十八块五。</p><p>她一周发了六十四条，四十一条里有数字。</p><p>我这周发了八十九条，里面我讲的是：公司那个系统难用、陈树要结婚了、我那个腰又疼了、二月的排班还没出。</p><p>第二周，她在查地方。</p><p>她发了很多张图。</p><p>一个酒店的外墙。</p><p>一个换车站。</p><p>一张公交时间表，她拿手机拍屏，拍糊了，她又拍了一次。</p><p>一张地图的截图，上面有她画的红线。</p><p>她在地图上用红线把她那八天要走的路画出来。</p><p>她发过来的时候写了一句：&quot;你看我这一圈。&quot;</p><p>我这周回的是什么，我读到了。</p><p>我回的是：&quot;那你那两天不是白坐在酒店。&quot;</p><p>她没回。</p><p>隔了两天，她自己发了一条别的，把这一页翻过去了。</p><p>第三周，她在置办东西。</p><p>她发了五样她要带的东西。</p><p>一支笔。</p><p>一本画册。</p><p>一个眼罩，她说就是那个九块十九个晚上都不压眼睛的那个，带子松两格，她拿胶布把松出来的那一截粘住了。</p><p>一张彩铅画的画，画上是两个人站在一条路上，背面她写了三个字，她说那是她唯一一张没卖出去也不打算卖的。</p><p>一张瓶签上剪下来的小条。</p><p>她说这张瓶签她留了六年，她说她要拿来跟那张凑成一次。</p><p>她说她为了这件事特意去配了一根绳子。</p><p>我这周在干什么。</p><p>我这周在跟我一个同事吵架。</p><p>我在她那边发了四十多条，讲的全是我那个同事怎么不讲理。</p><p>她一条一条回。</p><p>她回的全是&quot;嗯&quot;&quot;那你怎么办&quot;&quot;别理他&quot;&quot;你要不要跟你们领导说&quot;。</p><p>第四周，她在办签证的延期。</p><p>她那天发了一句：我今天在那个大厅排了三个钟头。</p><p>我说：三个钟头你干什么了。</p><p>她说：我在算我从你那个站出来往哪边走。</p><p>她说：我发现你那个站有两个出口。</p><p>她说：你不知道哪个出口离你近，你要提前告诉我。</p><p>我说：我到时候讲。</p><p>她说：你现在不知道吗。</p><p>我说：我现在不知道，我要问了才知道。</p><p>她说：好。</p><p>她说：那你问了告诉我。</p><p>我这周没有问。</p><p>我把这件事放下了。</p><p>第五周，她开始把她的图交完。</p><p>她每天夜里画到三点。</p><p>她发过来的是她那张画到一半的东西。</p><p>她说，这张我要带过去给你看。</p><p>我说，为什么。</p><p>她说，因为这张我还没画完，画完的那张我不给你看。</p><p>她说，画完的那张是要挂出来的。</p><p>她说，画不完的这张是我这几天的样子。</p><p>我那天晚上没回。</p><p>我以为我是累了。</p><p>我今年读到这里我知道我不是累。</p><p>我是不敢接。</p><p>我要是那天回一句&quot;我等这张&quot;，我这四天就要开始想二月。</p><p>我要是想二月，我那天晚上就要承认我在等一个人来。</p><p>我在等一个人来，等于我这六年还没到头。</p><p>我不想还没到头。</p><p>第六周她发了那张订单截图。</p><p>第七周她开始给我念那个酒店有什么。</p><p>那周有一天她发了一句很短的话，我没接。</p><p>她说，我今天跟我姨说我过年回。</p><p>她说，我讲完我改口了。</p><p>我说，为什么改。</p><p>她说，没什么。</p><p>我说，那是什么。</p><p>她说，我说完“我回”那一下，我心里想的是你那个城市。</p><p>她说，我不是想我们那个家。</p><p>她说，我怕我讲错了，我重新讲一句“我不回了”。</p><p>她说，我讲完这句我站在那个厨房里，我姨把那个锅盖上。</p><p>她说，她说“你今年怎么这么多心事”。</p><p>她说，我说没有。</p><p>她说，我这辈子“没有”这两个字讲得比名字顺。</p><p>我那天回的是：哦。</p><p>她说这个酒店房间里有一个水壶。</p><p>她说有水壶我就不带泡面了。</p><p>她说她带了两包纸巾，她说你那儿的人吃饭爱洒。</p><p>她说她把那张瓶签用绳子系好了。</p><p>她说她那天晚上把那个包打好了放在门口，她看了三次。</p><p>她说她说她自己这样很像要出远门的小孩。</p><p>我第七周在干什么。</p><p>我第七周在给一个朋友回一条很长的消息。</p><p>那个朋友问我说，你到底还打算这样多久。</p><p>我回他的是：我跟她之间更像是一种我欠她的东西。</p><p>我回他的是：我更像在赎罪。</p><p>我回他的是：我要是把这段走完，我就自由了。</p><p>那三条我发出去的时间，是那天晚上八点四十一到八点五十七。</p><p>她那边那一条&quot;我把包打好了放在门口，我看了三次&quot;，发在同一天下午两点四十九。</p><p>第八周。</p><p>第八周有一天，她发了一句很短的话。</p><p>那句话我今天读出来，我坐在椅子上很久。</p><p>她发的是：</p><p>她说，你为什么最近不讲二月的事。</p><p>我说，我讲什么。</p><p>她说，二月十九号那天你要不要请假。</p><p>我说，你那个不是定了吗。</p><p>她说，定了。</p><p>她说，我就是想听你讲一次那天你要怎么过。</p><p>我说，我那天接你，然后吃饭。</p><p>她说，然后呢。</p><p>我说，然后你住那家。</p><p>她说，然后呢。</p><p>我说，你要我讲什么。</p><p>她说，我要你讲一句你想我。</p><p>她说，你只要讲一句，我这一个月画图我就不难受了。</p><p>我那天回的是：</p><p>我说，你想多了。</p><p>这三个字我发过很多次。</p><p>我今年数出来，我这十一年跟她讲过二十七次&quot;你想多了&quot;。</p><p>每一次她讲的都是一句真话。</p><p>那八周里，她在算四件事：钱、地方、要带什么、我那天怎么过。</p><p>我那八周里在算一件事：这段关系什么时候能结清。</p><p>她二月十九号从那边出发，坐六个钟头的车，换一次公交，走那个我不知道是哪个的出口。</p><p>那一年二月十九号那天，我在会议室里做汇报。</p><p>我提前两天跟她讲，我那天要开会，你晚一天到。</p><p>她把票改了。</p><p>她改到二十号。</p><p>她改签花了三百一十块。</p><p>她那天没有告诉我这三百一十块。</p><p>我是今年打印这十六页的时候，在她那一个&quot;改签成功&quot;的截图底下看见的。</p><p>那八周里，她在攒一次见面。</p><p>我在看一个结局。</p><p>我今天才知道。</p>',136)])])}const l=t(_,[["render",u]]);export{d as __pageData,l as default};
